function unavailable(hazard: RiskItem["hazard"], source: SourceInfo, now: number): RiskItem {
  return {
    hazard,
    level: null,
    source,
    updatedAt: now,
    validUntil: null,
    summary: "ChÆ°a láº¥y Ä‘Æ°á»£c dá»¯ liá»‡u tá»« nguá»“n chÃ­nh thá»©c. Sáº½ thá»­ láº¡i tá»± Ä‘á»™ng.",
    details: [],
  };
}

export function buildReport(
  lat: number,
  lon: number,
  weatherJson: OpenMeteoJson | null,
  quakeJson: UsgsJson | null,
  now: number,
): RiskReport {
  const current = weatherJson ? parseCurrent(weatherJson, now) : null;
  const wItems = weatherJson
    ? weatherItems(weatherJson, current, now)
    : (["rain", "flood", "flash", "storm", "landslide"] as const).map((h) => unavailable(h, MODEL_SOURCE, now));

  const quakes = quakeJson ? parseQuakes(quakeJson, lat, lon) : [];
  const gItems = quakeJson
    ? geoItems(quakes, num(quakeJson.metadata?.generated) || now, now)
    : (["quake", "aftershock", "tsunami"] as const).map((h) =>
        unavailable(h, h === "tsunami" ? TSUNAMI_SOURCE : USGS_SOURCE, now),
      );

  const items = [...wItems, ...gItems];
  return {
    lat,
    lon,
    elevation: weatherJson && typeof weatherJson.elevation === "number" ? weatherJson.elevation : null,
    generatedAt: now,
    weather: current,
    weatherError: !weatherJson,
    quakeError: !quakeJson,
    items,
    quakes: quakes.filter((q) => q.distanceKm <= 1500).slice(0, 40),
    overall: maxLevel(items),
  };
}
